(5361, 'Xderm N', 'Clobetasol Propionate + Neomycin Sulphate + Nystatin (0.5 mg+5 mg+1 Lac IU)/gm', 60.00, 1, 'tube', '1 tube cream', 'Cream', '10 gm', 'yes', 'no', NULL, 'active', '1614_1743952755.jpg', 69, 12, 'mahidsiam1@gmail.com', '2025-04-06 19:19:15', '2025-04-06 19:19:15'),
(5362, 'Rejubion', 'Vitamin B1, B6 & B12 (100 mg+100 mg+1 mg)/3 ml', 25.17, 1, 'x 3 ml ampoule', '3 ml ampoule', 'Injection', '(100 mg+100 mg+1 mg)/3 ml', 'yes', 'no', '<p><br></p>', 'active', '532_1743952956.webp', 55, 12, 'mahidsiam1@gmail.com', '2025-04-06 19:22:36', '2025-05-06 07:48:21'),
(5363, 'Salomax', 'Salbutamol', 0.46, 10, 'tablet', '10 tablet in a strip', 'Tablet', '4 mg', 'yes', 'no', NULL, 'active', '1924_1743953045.webp', 26, 12, 'mahidsiam1@gmail.com', '2025-04-06 19:24:05', '2025-04-06 19:24:05'),
(5364, 'Salomax', 'Salbutamol', 2.50, 10, 'capsule', '10 capsule in a strip', 'Capsule', '200 mcg', 'yes', 'no', NULL, 'active', '1989_1743953154.webp', 26, 12, 'mahidsiam1@gmail.com', '2025-04-06 19:25:54', '2025-04-06 19:25:54'),
