(5366, 'Supraplex', 'Vitamin B complex (5 mg+2 mg+2 mg+20 mg)/5 ml', 38.20, 1, 'x 200 ml bottle', '200 ml bottle', 'Syrup', '(5 mg+2 mg+2 mg+20 mg)/5 ml', 'yes', 'no', '<p><br></p>', 'active', '819_1743953502.webp', 9, 12, 'mahidsiam1@gmail.com', '2025-04-06 19:31:42', '2025-05-06 11:59:25'),
(5367, 'Supraplex', 'Vitamin B complex (5 mg+2 mg+2 mg+20 mg)/5 ml', 20.90, 1, 'x 100 ml bottle', '100 ml bottle', 'Syrup', '(5 mg+2 mg+2 mg+20 mg)/5 ml', 'yes', 'no', NULL, 'active', '1899_1743953539.webp', 9, 12, 'mahidsiam1@gmail.com', '2025-04-06 19:32:19', '2025-05-06 11:59:52'),
